import React from 'react';
import HeaderBar from './HeaderBar';
// Simplified Back Button component
const BackButton = ({ onClick, isEasyMode }) => (
    <button
        onClick={onClick}
        style={{
            position: 'absolute',
            top: '20px',
            left: '20px',
            padding: '10px 15px',
            backgroundColor: '#fff',
            border: '2px solid #ccc',
            borderRadius: '10px',
            cursor: 'pointer',
            fontSize: isEasyMode ? '24px' : '16px',
            fontWeight: 'bold',
            zIndex: 10,
            boxShadow: '0 2px 5px rgba(0,0,0,0.1)'
        }}
    >
        <span role="img" aria-label="Back">⬅️</span> Main Menu
    </button>
);

// Component for the three main services
const SubIcon = ({ name, emoji, goToPage, pageTarget, isEasyMode }) => (
    <div 
        onClick={() => goToPage(pageTarget)}
        style={{
            padding: '25px 15px',
            margin: '15px 10%', // Use percentage margin for better centering
            border: '4px solid #007bff',
            borderRadius: '15px',
            width: '80%', // Takes up most of the width
            textAlign: 'center',
            backgroundColor: '#e6f7ff', // Very light blue background
            cursor: 'pointer',
            boxShadow: '0 8px 15px rgba(0,0,0,0.2)', // Clear 3D effect
            transition: 'transform 0.1s, box-shadow 0.1s',
        }}
        onMouseOver={e => e.currentTarget.style.boxShadow = '0 10px 20px rgba(0,0,0,0.3)'}
        onMouseOut={e => e.currentTarget.style.boxShadow = '0 8px 15px rgba(0,0,0,0.2)'}
    >
        {/* Emoji Icon: Large, but not excessively huge */}
        <span role="img" aria-label={name} style={{
            fontSize: isEasyMode ? '80px' : '50px', 
            display: 'block', 
            marginBottom: '10px'
        }}>{emoji}</span>
        
        {/* Name/Label: Clear, bold text */}
        <p style={{
            fontWeight: '900', // Extra bold
            fontSize: isEasyMode ? '30px' : '20px', 
            color: '#004085', // Dark blue text
            margin: '0'
        }}>{name}</p>
    </div>
);

function MedicalDashboard({ isEasyMode, goToPage }) {
    return (
        <div style={{ position: 'relative', minHeight: '400px', paddingBottom: '20px' }}>
            
            {/* Replace BackButton and H2 with HeaderBar */}
            <HeaderBar
                title="Medical Menu"
                onBackClick={() => goToPage('dashboard')} // Goes back to the main dashboard
                isEasyMode={isEasyMode}
            />

            {/* ... (Icon Grid/List remains the same, remove the old H2 and back button) ... */}
        </div>
    );
}

export default MedicalDashboard;
